// Package secret encrypts imported credentials (kubeconfigs, SSH private keys) at rest with
// AES-256-GCM.
//
// The key is generated by the application on first use and kept in <data dir>/secret.key
// (mode 0600), or derived from the DKM_SECRET_KEY environment variable when that is set —
// which lets a server deployment keep the key out of the data volume.
package secret

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// magic prefixes every sealed blob so plaintext files left by older versions can be told apart.
var magic = []byte("DKM1")

// Box seals and opens small secrets.
type Box struct {
	aead cipher.AEAD
	// Source says where the key came from: "env" or the key file path.
	Source string
}

// Open loads the key for a data directory, generating one on first use.
func Open(dir string) (*Box, error) {
	var key []byte
	source := "env"
	if env := os.Getenv("DKM_SECRET_KEY"); env != "" {
		sum := sha256.Sum256([]byte(env))
		key = sum[:]
	} else {
		path := filepath.Join(dir, "secret.key")
		source = path
		b, err := os.ReadFile(path)
		switch {
		case err == nil:
			key, err = hex.DecodeString(strings.TrimSpace(string(b)))
			if err != nil || len(key) != 32 {
				return nil, fmt.Errorf("密钥文件 %s 已损坏（应为 64 位十六进制）", path)
			}
		case errors.Is(err, os.ErrNotExist):
			key = make([]byte, 32)
			if _, err := rand.Read(key); err != nil {
				return nil, err
			}
			if err := os.WriteFile(path, []byte(hex.EncodeToString(key)+"\n"), 0o600); err != nil {
				return nil, fmt.Errorf("写入密钥文件失败: %w", err)
			}
		default:
			return nil, err
		}
	}
	block, err := aes.NewCipher(key)
	if err != nil {
		return nil, err
	}
	aead, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	return &Box{aead: aead, Source: source}, nil
}

// Sealed reports whether b was produced by Seal.
func Sealed(b []byte) bool { return len(b) > len(magic) && string(b[:len(magic)]) == string(magic) }

// Seal encrypts plain. Output: magic | nonce | ciphertext+tag.
func (b *Box) Seal(plain []byte) ([]byte, error) {
	nonce := make([]byte, b.aead.NonceSize())
	if _, err := rand.Read(nonce); err != nil {
		return nil, err
	}
	out := append([]byte{}, magic...)
	out = append(out, nonce...)
	return b.aead.Seal(out, nonce, plain, magic), nil
}

// Unseal decrypts a blob produced by Seal.
func (b *Box) Unseal(blob []byte) ([]byte, error) {
	if !Sealed(blob) {
		return nil, errors.New("数据不是加密格式")
	}
	blob = blob[len(magic):]
	n := b.aead.NonceSize()
	if len(blob) < n {
		return nil, errors.New("加密数据不完整")
	}
	plain, err := b.aead.Open(nil, blob[:n], blob[n:], magic)
	if err != nil {
		return nil, errors.New("解密失败：密钥不匹配（secret.key 被替换，或 DKM_SECRET_KEY 变了）")
	}
	return plain, nil
}

// WriteFile seals data and writes it atomically with mode 0600.
func (b *Box) WriteFile(path string, plain []byte) error {
	sealed, err := b.Seal(plain)
	if err != nil {
		return err
	}
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, sealed, 0o600); err != nil {
		return err
	}
	return os.Rename(tmp, path)
}

// ReadFile reads and unseals a file written by WriteFile.
func (b *Box) ReadFile(path string) ([]byte, error) {
	blob, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	return b.Unseal(blob)
}
